async def handle_audio_request(websocket, request):
    sound_id = request['sound_id']

    # Check cache eerst (0.03ms)
    if sound_id in audio_cache:
        return audio_cache[sound_id]

    # Genereer procedurele fallback (20ms)
    procedural = generate_procedural(request['type'])

    # Wacht AI generatie in achtergrond
    asyncio.create_task(
        generate_ai_audio(sound_id, request)
    )

    return procedural
