**Unreal Engine 5 - Thread-Safe Audio:**
```cpp
void UAudioManager::OnAudioReceived(const TArray<uint8>& Data)
{
    // Moet USoundWave op game thread maken
    AsyncTask(ENamedThreads::GameThread, [this, Data]()
    {
        USoundWave* Sound = NewObject<USoundWave>();
        Sound->RawData.Lock(LOCK_READ_WRITE);
        // ... verwerk audiodata
        PlaySound(Sound);
    });
}
```

